const CommentList = ({ post }) => {
  const renderedComments = post.comments.map((comment) => {
    return <li key={comment.id}>{comment.content}</li>;
  });

  return (
    <div>
      Comment list
      <ul>{renderedComments}</ul>
    </div>
  );
};

export default CommentList;
